  --danger: #ef4444;
  --warning: #f59e0b;
  --border: #e2e8f0;
  --shadow: 0 1px 3px rgba(0,0,0,.06), 0 1px 2px rgba(0,0,0,.04);
  --shadow-lg: 0 10px 15px -3px rgba(0,0,0,.08), 0 4px 6px -4px rgba(0,0,0,.05);
}}
* {{ margin:0; padding:0; box-sizing:border-box; }}
body {{
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', sans-serif;
  background: var(--bg);
  color: var(--text);
  line-height: 1.6;
}}
.container {{ max-width: 1180px; margin: 0 auto; padding: 24px 20px; }}

/* Header */
.header {{
  background: linear-gradient(135deg, #1e293b 0%, #334155 100%);
  color: white;
  padding: 48px 20px;
  text-align: center;
  margin-bottom: 32px;
}}
.header h1 {{ font-size: 2rem; font-weight: 700; margin-bottom: 8px; letter-spacing: -0.5px; }}
.header .subtitle {{ font-size: 1.05rem; opacity: 0.85; max-width: 700px; margin: 0 auto; }}

/* Cards */
.card {{
  background: var(--card);
  border-radius: 12px;
  padding: 28px;
  margin-bottom: 24px;
  box-shadow: var(--shadow);
  border: 1px solid var(--border);
}}
.card h2 {{
  font-size: 1.35rem;
  font-weight: 700;
  color: var(--primary-dark);
  margin-bottom: 4px;
  border-left: 4px solid var(--primary);
  padding-left: 12px;
}}
.card h3 {{
  font-size: 1.1rem;
  font-weight: 600;
  color: var(--text);
  margin: 20px 0 10px;
}}
.card p, .card li {{ color: var(--text-muted); font-size: 0.95rem; margin-bottom: 6px; }}
.card ul {{ padding-left: 20px; }}

/* KPI strip */
.kpi-strip {{
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(170px, 1fr));
  gap: 16px;
  margin-bottom: 24px;
}}
.kpi {{
  background: var(--card);
  border-radius: 10px;
  padding: 20px 16px;
  text-align: center;
  box-shadow: var(--shadow);
  border: 1px solid var(--border);
}}
.kpi .value {{ font-size: 1.8rem; font-weight: 800; color: var(--primary-dark); }}
.kpi .label {{ font-size: 0.82rem; color: var(--text-muted); margin-top: 2px; text-transform: uppercase; letter-spacing: 0.3px; }}
.kpi.green .value {{ color: #059669; }}
.kpi.amber .value {{ color: #d97706; }}
.kpi.red .value {{ color: #dc2626; }}

/* Chart wrapper */
.chart-wrap {{
  position: relative;
  margin: 18px 0;
  max-width: 100%;
}}
.chart-wrap canvas {{ max-height: 380px; }}

/* Tables */
.data-table {{
  width: 100%;
  border-collapse: collapse;
  margin: 14px 0;
  font-size: 0.9rem;
}}
.data-table th {{
  background: #f1f5f9;
  padding: 10px 12px;
  text-align: left;
  font-weight: 600;
  color: var(--text);
  border-bottom: 2px solid var(--border);
  white-space: nowrap;
}}
.data-table td {{
  padding: 9px 12px;
  border-bottom: 1px solid var(--border);
  color: var(--text-muted);
}}
.data-table tr:hover td {{ background: #f8fafc; }}
.data-table .num {{ text-align: right; font-variant-numeric: tabular-nums; }}
.pill {{
  display: inline-block;
  padding: 2px 10px;
  border-radius: 999px;
  font-size: 0.78rem;
  font-weight: 600;
}}
.pill-white {{ background: #dbeafe; color: #1e40af; }}
.pill-black {{ background: #fce7f3; color: #9d174d; }}
.pill-draw {{ background: #f1f5f9; color: #475569; }}

/* Insights box */
.insight-box {{
  background: #eff6ff;
  border-left: 4px solid var(--primary);
  padding: 14px 18px;
  border-radius: 0 8px 8px 0;
  margin: 14px 0;
  font-size: 0.93rem;
  color: var(--text);
}}

/* Section divider */
.section {{ scroll-margin-top: 20px; }}

/* Two-col grid */
.grid-2 {{ display: grid; grid-template-columns: 1fr 1fr; gap: 20px; }}
@media (max-width: 768px) {{ .grid-2 {{ grid-template-columns: 1fr; }} }}

/* Footer */
.footer {{
  text-align: center;
  color: var(--text-muted);
  font-size: 0.82rem;
  padding: 32px 0 16px;
  border-top: 1px solid var(--border);
  margin-top: 24px;
}}

/* TOC */
.toc {{ list-style: none; padding: 0; columns: 2; column-gap: 32px; }}
.toc li {{ margin-bottom: 6px; }}
.toc a {{ color: var(--primary); text-decoration: none; font-size: 0.95rem; }}
.toc a:hover {{ text-decoration: underline; }}
@media (max-width: 600px) {{ .toc {{ columns: 1; }} }}
</style>
</head>
<body>

<div class="header">
  <h1>Lichess Chess Game Analytics</h1>
  <p class="subtitle">Patterns of Victory, Openings, and Player Dynamics &mdash; a data-driven analysis of {total_games:,} games</p>
</div>

<div class="container">

<!-- TOC -->
<div class="card">
  <h2>Table of Contents</h2>
  <ul class="toc">
    <li><a href="#overview">1. Dataset Overview &amp; Game Distribution</a></li>
    <li><a href="#color-advantage">2. White vs. Black: The First-Move Advantage</a></li>
    <li><a href="#rating-analysis">3. Rating Dynamics and Their Impact on Outcomes</a></li>
    <li><a href="#opening-strategy">4. Opening Analysis: Popular Openings and Their Success Rates</a></li>
    <li><a href="#time-control">5. Time Control Patterns and Game Characteristics</a></li>
    <li><a href="#key-findings">6. Key Findings and Strategic Takeaways</a></li>
  </ul>
</div>

<!-- ─── Section 1 ──────────────────────────────────────────────────────── -->
<div class="section" id="overview">
<div class="card">
  <h2>1. Dataset Overview &amp; Game Distribution</h2>
  <p>A high-level snapshot of the {total_games:,} Lichess games under analysis.</p>

  <div class="kpi-strip" style="margin-top:18px">
    <div class="kpi"><div class="value">{total_games:,}</div><div class="label">Total Games</div></div>
    <div class="kpi green"><div class="value">{rated_pct:.1f}%</div><div class="label">Rated Games</div></div>
    <div class="kpi"><div class="value">{avg_game_length}</div><div class="label">Avg. Turns</div></div>
    <div class="kpi amber"><div class="value">{checkmate_rate}%</div><div class="label">Checkmate Rate</div></div>
    <div class="kpi"><div class="value">{resign_rate}%</div><div class="label">Resignation Rate</div></div>
  </div>

  <div class="grid-2">
    <div>
      <h3>Game Outcomes by Winner</h3>
      <div class="chart-wrap"><canvas id="chartWinnerDist"></canvas></div>
    </div>
    <div>
      <h3>Victory Status Distribution</h3>
      <div class="chart-wrap"><canvas id="chartVictoryStatus"></canvas></div>
    </div>
  </div>

  <div class="insight-box">
    <strong>Key snapshot:</strong> Of {total_games:,} games, {rated_pct:.1f}% were rated. Resignation is the most common game-end mode at {resign_rate}%, followed by checkmate at {checkmate_rate}%. Draws account for {draw_rate_vs}% of all games, making Lichess a predominantly decisive platform.
  </div>
</div>
</div>

<!-- ─── Section 2 ──────────────────────────────────────────────────────── -->
<div class="section" id="color-advantage">
<div class="card">
  <h2>2. White vs. Black: The First-Move Advantage</h2>
  <p>Quantifying white's edge overall, by victory status, rating bracket, and time control.</p>

  <div class="kpi-strip" style="margin-top:18px">
    <div class="kpi"><div class="value">{white_win_rate_all:.1f}%</div><div class="label">White Win Rate (all)</div></div>
    <div class="kpi red"><div class="value">{black_win_rate_all:.1f}%</div><div class="label">Black Win Rate (all)</div></div>
    <div class="kpi amber"><div class="value">{white_win_rate_decisive:.1f}%</div><div class="label">White Win (decisive only)</div></div>
    <div class="kpi"><div class="value">{draw_rate_all:.1f}%</div><div class="label">Draw Rate</div></div>
  </div>

  <h3>White Advantage by Victory Status</h3>
  <div class="chart-wrap"><canvas id="chartColorByVStatus"></canvas></div>

  <h3>White Advantage by Rating Bracket</h3>
  <p>Decisive-game win rates grouped by average game rating.</p>
  <div class="chart-wrap"><canvas id="chartColorByBracket"></canvas></div>

  <h3>White Advantage by Time Control (Top 8)</h3>
  <div class="chart-wrap"><canvas id="chartColorByTC"></canvas></div>

  <div class="insight-box">
    <strong>First-move advantage:</strong> White wins {white_win_rate_decisive:.1f}% of decisive games vs. black's {black_win_rate_decisive:.1f}%, a consistent {white_win_rate_decisive - black_win_rate_decisive:.1f}-point edge. This advantage persists across all rating brackets and time controls, though the magnitude shifts — <span id="insightBracketNote"></span>
  </div>
</div>
</div>

<!-- ─── Section 3 ──────────────────────────────────────────────────────── -->
<div class="section" id="rating-analysis">
<div class="card">
  <h2>3. Rating Dynamics and Their Impact on Outcomes</h2>

  <div class="kpi-strip" style="margin-top:18px">
    <div class="kpi"><div class="value">{avg_white_rating}</div><div class="label">Avg White Rating</div></div>
    <div class="kpi"><div class="value">{avg_black_rating}</div><div class="label">Avg Black Rating</div></div>
    <div class="kpi green"><div class="value">{corr_diff_win}</div><div class="label">Rating Diff ↔ Win Corr.</div></div>
  </div>

  <h3>Rating Distribution</h3>
  <div class="chart-wrap"><canvas id="chartRatingDist"></canvas></div>

  <h3>Rating Differential vs. Higher-Rated Player Win Probability</h3>
  <p>Binned by absolute rating gap (decisive games only). A positive differential means the higher-rated player is more likely to win.</p>
  <div class="chart-wrap"><canvas id="chartDiffImpact"></canvas></div>

  <h3>Average Game Length by Rating Tier</h3>
  <div class="chart-wrap"><canvas id="chartLengthByTier"></canvas></div>

  <div class="insight-box">
    <strong>Rating matters:</strong> The correlation between rating differential and higher-rated-player wins is {corr_diff_win}. Even a 50-point gap yields a noticeable edge; a 200+ point gap pushes the higher-rated player's win probability above 60%. Longer games correlate with higher-rated players — experts average more turns, suggesting deeper positional play.
  </div>
</div>
</div>

<!-- ─── Section 4 ──────────────────────────────────────────────────────── -->
<div class="section" id="opening-strategy">
<div class="card">
  <h2>4. Opening Analysis: Popular Openings and Their Success Rates</h2>

  <h3>Top 15 Openings by ECO Code</h3>
  <div class="chart-wrap"><canvas id="chartTopOpenings"></canvas></div>

  <h3>Win Rates for Top 15 Openings by Name</h3>
  <div style="overflow-x:auto">
  <table class="data-table" id="tableOpenings">
    <thead>
      <tr><th>#</th><th>Opening</th><th>Games</th><th class="num">White %</th><th class="num">Black %</th><th class="num">Draw %</th></tr>
    </thead>
    <tbody></tbody>
  </table>
  </div>

  <h3>Openings Where Black Outperforms White (min 50 games)</h3>
  <div style="overflow-x:auto">
  <table class="data-table" id="tableBlackFavored">
    <thead>
      <tr><th>ECO</th><th>Opening</th><th>Games</th><th class="num">White %</th><th class="num">Black %</th><th class="num">Draw %</th></tr>
    </thead>
    <tbody></tbody>
  </table>
  </div>

  <h3>Opening Depth (Ply) vs. Outcome</h3>
  <div class="chart-wrap"><canvas id="chartDepthStats"></canvas></div>

  <div class="insight-box">
    <strong>Opening insight:</strong> The most popular ECO codes are dominated by king's pawn and queen's pawn systems. While white typically holds a slight edge across openings, certain defenses give black a decisive statistical edge — see the "Black-Favored Openings" table above for specifics.
  </div>
</div>
</div>

<!-- ─── Section 5 ──────────────────────────────────────────────────────── -->
<div class="section" id="time-control">
<div class="card">
  <h2>5. Time Control Patterns and Game Characteristics</h2>

  <h3>Top 10 Time Controls by Frequency</h3>
  <div class="chart-wrap"><canvas id="chartTCFreq"></canvas></div>

  <h3>Game Length by Time Control</h3>
  <div class="chart-wrap"><canvas id="chartTCLength"></canvas></div>

  <h3>Victory Status by Time Control Category</h3>
  <div class="chart-wrap"><canvas id="chartTCVStatus"></canvas></div>

  <h3>White Advantage by Time Control Category</h3>
  <div class="chart-wrap"><canvas id="chartTCColorAdv"></canvas></div>

  <div class="insight-box">
    <strong>Time control insight:</strong> Bullet and blitz formats see significantly more timeouts and shorter games. Classical and long time controls produce more draws and checkmates, with resignation rates remaining high across all formats. White's advantage tends to <span id="insightTCNote"></span>
  </div>
</div>
</div>

<!-- ─── Section 6 ──────────────────────────────────────────────────────── -->
<div class="section" id="key-findings">
<div class="card">
  <h2>6. Key Findings and Strategic Takeaways</h2>

  <h3>The First-Move Advantage is Real and Consistent</h3>
  <p>White wins <strong>{white_win_rate_decisive:.1f}%</strong> of decisive games, a <strong>{white_win_rate_decisive - black_win_rate_decisive:.1f}-point</strong> edge over black. This advantage holds across every rating bracket and time control analyzed, though it narrows slightly at the highest rating tiers where players are better equipped to neutralize white's initiative.</p>

  <h3>Rating Differentials Are Predictive</h3>
  <p>The correlation between rating differential and higher-rated player wins (r = <strong>{corr_diff_win}</strong>) confirms that even modest rating gaps translate into measurable win-probability shifts. A 100-point gap yields roughly a 55-58% win rate for the stronger player; at 300+ points, the probability climbs above 65%. Coaches should note that upsets are the exception, not the norm.</p>

  <h3>Resignation Dominates, but Checkmate Rates Vary by Time Control</h3>
  <p>Overall, <strong>{resign_rate}%</strong> of games end by resignation vs. <strong>{checkmate_rate}%</strong> by checkmate. However, in bullet/ultra-bullet formats, timeouts surge and checkmate rates drop, while longer time controls see checkmate climb above the overall average — players with more time convert advantages to mate rather than accepting resignation.</p>

  <h3>Opening Choice Matters — Some Defenses Favor Black</h3>
  <p>While white holds the aggregate edge, specific openings reverse the trend. Among openings with 50+ games, several ECO codes show black winning more often than white, suggesting that theoretically sound defenses can neutralize or even reverse white's first-move advantage when played by prepared opponents.</p>

  <h3>Game Depth Correlates with Player Strength</h3>
  <p>Expert-tier games (1800+ average rating) average noticeably more turns than beginner games, indicating that stronger players navigate deeper into endgames rather than falling to early tactical blows. Opening depth (number of book moves) also correlates with game length and outcome distributions.</p>

  <h3>Time Control Shapes Game Character</h3>
  <p>Bullet games are chaotic — shorter, timeout-heavy, with a slightly different white-advantage profile. Classical games are more "chess-like": longer, more draws, higher checkmate rates, and a more pronounced rating effect. Players choosing time controls should understand these structural differences when interpreting their own statistics.</p>
</div>
</div>

<div class="footer">
  Data source: Lichess.org via Kaggle (datasnaek/chess) &bull; {total_games:,} games &bull; Report generated with Python, pandas &amp; Chart.js
</div>

</div><!-- /container -->

<script>
const D = {payload_json};

/* ── Helpers ────────────────────────────────────────────────────────────── */
const palette = {{
  blue: '#3b82f6', blueLight: 'rgba(59,130,246,.25)',
  pink: '#ec4899', pinkLight: 'rgba(236,72,153,.25)',
  gray: '#94a3b8', grayLight: 'rgba(148,163,184,.25)',
  green: '#10b981', amber: '#f59e0b', red: '#ef4444',
  slate: '#475569', slateLight: '#e2e8f0'
}};

function makeChart(id, cfg) {{
  const ctx = document.getElementById(id);
  if (!ctx) return;
  cfg.options = cfg.options || {{}};
  cfg.options.responsive = true;
  cfg.options.maintainAspectRatio = true;
  cfg.options.plugins = cfg.options.plugins || {{}};
  cfg.options.plugins.legend = cfg.options.plugins.legend || {{ position: 'bottom', labels: {{ padding: 14, usePointStyle: true, font: {{ size: 12 }} }} }};
  new Chart(ctx, cfg);
}}

/* ── 1. Overview charts ───────────────────────────────────────────────── */
makeChart('chartWinnerDist', {{
  type: 'doughnut',
  data: {{
    labels: ['White', 'Black', 'Draw'],
    datasets: [{{ data: [D.winner_data.white, D.winner_data.black, D.winner_data.draw],
      backgroundColor: [palette.blue, palette.pink, palette.gray] }}]
  }},
  options: {{ plugins: {{ legend: {{ position: 'right' }} }} }}
}});

makeChart('chartVictoryStatus', {{
  type: 'doughnut',
  data: {{
    labels: Object.keys(D.victory_data),
    datasets: [{{ data: Object.values(D.victory_data),
      backgroundColor: [palette.green, palette.amber, palette.red, palette.gray] }}]
  }},
  options: {{ plugins: {{ legend: {{ position: 'right' }} }} }}
}});

/* ── 2. Color advantage charts ─────────────────────────────────────────── */
// By victory status
(() => {{
  const labels = Object.keys(D.color_by_vstatus);
  const wPcts = labels.map(k => D.color_by_vstatus[k].white_pct);
  const bPcts = labels.map(k => D.color_by_vstatus[k].black_pct);
  makeChart('chartColorByVStatus', {{
    type: 'bar',
    data: {{
      labels: labels.map(l => l.charAt(0).toUpperCase()+l.slice(1)),
      datasets: [
        {{ label: 'White %', data: wPcts, backgroundColor: palette.blue }},
        {{ label: 'Black %', data: bPcts, backgroundColor: palette.pink }}
      ]
    }},
    options: {{ scales: {{ y: {{ beginAtZero: true, max: 80, ticks: {{ callback: v => v+'%' }} }} }} }}
  }});
}})();

// By rating bracket
(() => {{
  const labels = Object.keys(D.color_by_bracket);
  const wPcts = labels.map(k => D.color_by_bracket[k].white_dec_pct);
  const bPcts = labels.map(k => D.color_by_bracket[k].black_dec_pct);
  makeChart('chartColorByBracket', {{
    type: 'bar',
    data: {{
      labels, datasets: [
        {{ label: 'White %', data: wPcts, backgroundColor: palette.blue }},
        {{ label: 'Black %', data: bPcts, backgroundColor: palette.pink }}
      ]
    }},
    options: {{ scales: {{ y: {{ beginAtZero: true, max: 70, ticks: {{ callback: v => v+'%' }} }} }} }}
  }});
  // dynamic insight
  const maxW = Math.max(...wPcts), minW = Math.min(...wPcts);
  const maxIdx = wPcts.indexOf(maxW), minIdx = wPcts.indexOf(minW);
  document.getElementById('insightBracketNote').textContent =
    `the ${labels[maxIdx]} bracket shows the largest white edge (${maxW}%), while ${labels[minIdx]} narrows it to ${minW}%.`;
}})();

// By time control
(() => {{
  const labels = Object.keys(D.color_by_tc);
  const wPcts = labels.map(k => D.color_by_tc[k].white_dec_pct);
  const bPcts = labels.map(k => D.color_by_tc[k].black_dec_pct);
  makeChart('chartColorByTC', {{
    type: 'bar',
    data: {{
      labels, datasets: [
        {{ label: 'White %', data: wPcts, backgroundColor: palette.blue }},
        {{ label: 'Black %', data: bPcts, backgroundColor: palette.pink }}
      ]
    }},
    options: {{ scales: {{ y: {{ beginAtZero: true, max: 70, ticks: {{ callback: v => v+'%' }} }} }} }}
  }});
}})();

/* ── 3. Rating dynamics charts ─────────────────────────────────────────── */
makeChart('chartRatingDist', {{
  type: 'bar',
  data: {{
    labels: D.rating_hist_labels,
    datasets: [
      {{ label: 'White Rating', data: D.white_hist, backgroundColor: palette.blueLight, borderColor: palette.blue, borderWidth: 1 }},
      {{ label: 'Black Rating', data: D.black_hist, backgroundColor: palette.pinkLight, borderColor: palette.pink, borderWidth: 1 }}
    ]
  }},
  options: {{
    scales: {{
      x: {{ ticks: {{ maxRotation: 60, font: {{ size: 9 }} }} }},
      y: {{ beginAtZero: true }}
    }}
  }}
}});

// Rating differential impact
(() => {{
  const labels = Object.keys(D.abs_diff_stats);
  const probs = labels.map(k => D.abs_diff_stats[k].win_prob);
  const counts = labels.map(k => D.abs_diff_stats[k].count);
  makeChart('chartDiffImpact', {{
    type: 'line',
    data: {{
      labels,
      datasets: [
        {{ label: 'Higher-Rated Win %', data: probs, borderColor: palette.blue, backgroundColor: palette.blueLight,
           fill: true, tension: 0.3, pointRadius: 5, pointHoverRadius: 7 }},
        {{ label: 'Game Count', data: counts, borderColor: palette.gray, backgroundColor: 'transparent',
           borderDash: [5,5], tension: 0.3, pointRadius: 3, yAxisID: 'y1' }}
      ]
    }},
    options: {{
      scales: {{
        y: {{ beginAtZero: false, min: 45, ticks: {{ callback: v => v+'%' }} }},
        y1: {{ position: 'right', beginAtZero: true, grid: {{ drawOnChartArea: false }} }}
      }}
    }}
  }});
}})();

// Game length by rating tier
(() => {{
  const labels = Object.keys(D.length_by_tier);
  const means = labels.map(k => D.length_by_tier[k].mean);
  const medians = labels.map(k => D.length_by_tier[k].median);
  makeChart('chartLengthByTier', {{
    type: 'bar',
    data: {{
      labels,
      datasets: [
        {{ label: 'Mean Turns', data: means, backgroundColor: palette.blue }},
        {{ label: 'Median Turns', data: medians, backgroundColor: palette.green }}
      ]
    }},
    options: {{ scales: {{ y: {{ beginAtZero: true }} }} }}
  }});
}})();

/* ── 4. Opening charts ─────────────────────────────────────────────────── */
// Top 15 by ECO
(() => {{
  const stats = D.opening_stats;
  makeChart('chartTopOpenings', {{
    type: 'bar',
    data: {{
      labels: stats.map(s => s.eco),
      datasets: [
        {{ label: 'White % (decisive)', data: stats.map(s => s.white_pct), backgroundColor: palette.blue }},
        {{ label: 'Black % (decisive)', data: stats.map(s => s.black_pct), backgroundColor: palette.pink }}
      ]
    }},
    options: {{
      indexAxis: 'y',
      scales: {{ x: {{ beginAtZero: true, max: 70, ticks: {{ callback: v => v+'%' }} }} }}
    }}
  }});
}})();

// Opening name table
(() => {{
  const tbody = document.querySelector('#tableOpenings tbody');
  D.opening_name_stats.forEach((s, i) => {{
    const tr = document.createElement('tr');
    tr.innerHTML = `<td>${{i+1}}</td><td>${{s.name}}</td><td class="num">${{s.total.toLocaleString()}}</td>
      <td class="num"><span class="pill pill-white">${{s.white_pct}}%</span></td>
      <td class="num"><span class="pill pill-black">${{s.black_pct}}%</span></td>
      <td class="num">${{s.draw_pct}}%</td>`;
    tbody.appendChild(tr);
  }});
}})();

// Black-favored table
(() => {{
  const tbody = document.querySelector('#tableBlackFavored tbody');
  D.black_favored.forEach(s => {{
    const tr = document.createElement('tr');
    tr.innerHTML = `<td>${{s.opening_eco}}</td><td>${{s.name}}</td><td class="num">${{s.total.toLocaleString()}}</td>
      <td class="num"><span class="pill pill-white">${{s.white_pct}}%</span></td>
      <td class="num"><span class="pill pill-black">${{s.black_pct}}%</span></td>
      <td class="num">${{(s.draws/s.total*100).toFixed(1)}}%</td>`;
    tbody.appendChild(tr);
  }});
}})();

// Depth stats
