    'victory_data': victory_data,
    'winner_data': winner_data,
    'white_win_rate_all': round(white_win_rate_all, 1),
    'black_win_rate_all': round(black_win_rate_all, 1),
    'draw_rate_all': round(draw_rate_all, 1),
    'white_win_rate_decisive': round(white_win_rate_decisive, 1),
    'black_win_rate_decisive': round(black_win_rate_decisive, 1),
    'color_by_vstatus': color_by_vstatus,
    'color_by_bracket': color_by_bracket,
    'color_by_tc': color_by_tc,
    'top_tc': top_tc,
    'avg_white_rating': avg_white_rating,
    'avg_black_rating': avg_black_rating,
    'med_white_rating': med_white_rating,
    'med_black_rating': med_black_rating,
    'std_white_rating': std_white_rating,
    'std_black_rating': std_black_rating,
    'rating_hist_labels': rating_hist_labels,
    'white_hist': white_hist.tolist(),
    'black_hist': black_hist.tolist(),
    'abs_diff_stats': abs_diff_stats,
    'corr_diff_win': corr_diff_win,
    'length_by_tier': length_by_tier,
    'opening_stats': opening_stats,
    'opening_name_stats': opening_name_stats,
    'black_favored': black_favored[['opening_eco', 'name', 'total', 'white_wins', 'black_wins', 'draws', 'white_pct', 'black_pct']].to_dict('records'),
    'depth_stats': depth_stats,
    'tc_top10_labels': tc_top10.index.tolist(),
    'tc_top10_values': tc_top10.values.tolist(),
    'tc_length': tc_length,
    'tc_vstatus': tc_vstatus,
    'tc_cat_stats': tc_cat_stats,
    'checkmate_rate': checkmate_rate,
    'resign_rate': resign_rate,
    'outoftime_rate': outoftime_rate,
    'draw_rate_vs': draw_rate_vs,
    'avg_game_length': avg_game_length,
    'median_game_length': median_game_length,
}

