    if len(sub) == 0:
        continue
    w = len(sub[sub['winner'] == 'white'])
    b = len(sub[sub['winner'] == 'black'])
    d = len(sub[sub['winner'] == 'draw'])
    dec = w + b
    depth_stats[cat] = {
        'total': int(len(sub)),
        'white_pct': round(w / dec * 100, 1) if dec > 0 else 0,
        'black_pct': round(b / dec * 100, 1) if dec > 0 else 0,
        'draw_pct': round(d / len(sub) * 100, 1),
        'avg_turns': round(sub['turns'].mean(), 1)
    }

# ─── Section 5: Time Control ─────────────────────────────────────────────────
tc_counts = df['increment_code'].value_counts()
tc_top10 = tc_counts.head(10)

