tc_length = {}
for tc in top_tc:
    sub = df[df['increment_code'] == tc]
    tc_length[tc] = {
        'mean_turns': round(sub['turns'].mean(), 1),
        'median_turns': round(sub['turns'].median(), 1),
        'count': int(len(sub))
    }

tc_vstatus = {}
for tc in top_tc:
    sub = df[df['increment_code'] == tc]
    total_tc = len(sub)
    vs_dist = sub['victory_status'].value_counts()
    tc_vstatus[tc] = {
        'mate_pct': round(vs_dist.get('mate', 0) / total_tc * 100, 1),
        'resign_pct': round(vs_dist.get('resign', 0) / total_tc * 100, 1),
        'outoftime_pct': round(vs_dist.get('outoftime', 0) / total_tc * 100, 1),
        'draw_pct': round(vs_dist.get('draw', 0) / total_tc * 100, 1),
        'count': int(total_tc)
    }

def categorize_tc(base):
    if base <= 3:
        return 'Bullet (1-3 min)'
    elif base <= 5:
        return 'Blitz (5 min)'
    elif base <= 10:
        return 'Rapid (10 min)'
    elif base <= 15:
        return 'Classical (15 min)'
    else:
        return 'Long (20+ min)'

df['tc_category'] = df['base_time'].apply(categorize_tc)
tc_cat_order = ['Bullet (1-3 min)', 'Blitz (5 min)', 'Rapid (10 min)', 'Classical (15 min)', 'Long (20+ min)']

tc_cat_stats = {}
for cat in tc_cat_order:
