        'resign_pct': round(vs_dist.get('resign', 0) / total_cat * 100, 1),
        'outoftime_pct': round(vs_dist.get('outoftime', 0) / total_cat * 100, 1),
        'avg_turns': round(sub['turns'].mean(), 1)
    }

# ─── Additional KPIs ──────────────────────────────────────────────────────────
